$("addBtn").onclick=()=>{const answer=$("answer").value.trim();if(!answer||!recordedBlob)return;const ok=addDraft({answer,blob:recordedBlob});recordedBlob=null;$("answer").value="";$("preview").pause();$("preview").hidden=true;$("preview").removeAttribute("src");if(recordedUrl)URL.revokeObjectURL(recordedUrl);recordedUrl=null;$("addBtn").disabled=true;$("clipStatus").textContent=tr("added");if(recordQueue.length){$("answer").value=recordQueue.shift();$("clipStatus").textContent=tr("speakStop")}renderDrafts();toast(ok?tr("recordAdded"):tr("duplicatesRemoved"))};
function renderDrafts(){$("draftCount").textContent=drafts.length+" "+tr("words");$("saveSet").disabled=!drafts.length;const box=$("drafts");box.innerHTML="";if(!drafts.length){box.innerHTML='<p class="muted">'+tr("draftEmpty")+'</p>';return}drafts.forEach((d,i)=>{const row=document.createElement("div");row.className="draft-row";row.innerHTML=`<span>${i+1}. ${escapeHTML(d.answer)}</span><small>${d.tts?tr("ttsVoice"):tr("audioReadyShort")}</small><button aria-label="${tr("removeRecording")}">×</button>`;row.querySelector("button").onclick=()=>{drafts.splice(i,1);renderDrafts()};box.appendChild(row)})}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
$("saveSet").onclick=async()=>{if(!drafts.length)return;try{const source=$("dedupeToggle").checked?drafts.filter((d,i,a)=>a.findIndex(x=>normalizeWord(x.answer)===normalizeWord(d.answer))===i):drafts;const entries=await Promise.all(source.map(async d=>d.tts?({answer:d.answer,tts:true,lang:d.lang||TTS_LANGS[language]||"en-GB",voiceURI:d.voiceURI||null,voiceName:d.voiceName||null,audio:null}):({answer:d.answer,audio:await blobToDataURL(d.blob),mime:d.blob.type})));const set={id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),name:$("setName").value.trim()||tr("setDefault"),entries,created:Date.now()};await dbPut(set);drafts=[];recordQueue=[];await refreshCount();toast(tr("saved"));show("library")}catch(e){toast(tr("saveFailed"))}};
function blobToDataURL(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob)})}
async function exportSet(set){const payload={format:"StudySonicSet",version:2,name:set.name,created:set.created,entries:set.entries};const blob=new Blob([JSON.stringify(payload)],{type:"application/json"});const file=new File([blob],(set.name||"study-set").replace(/[^a-z0-9-_ ]/gi,"").trim().replace(/\s+/g,"-")+"-StudySonic.json",{type:"application/json"});try{if(navigator.canShare?.({files:[file]})&&navigator.share){await navigator.share({title:tr("shareTitle"),text:tr("shareText"),files:[file]});}else{const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}toast(LANGS[language].exported)}catch(e){if(e.name!=="AbortError")toast(tr("shareFailed"))}}
$("importSetBtn").onclick=()=>$("importFile").click();
$("importFile").onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{const data=JSON.parse(await file.text());if(data.format!=="StudySonicSet"||!Array.isArray(data.entries)||!data.entries.length||data.entries.some(x=>typeof x.answer!=="string"||(!(x.tts===true)&&!(typeof x.audio==="string"&&x.audio.startsWith("data:audio/")))))throw Error("invalid");const imported={id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),name:String(data.name||tr("importedName")).slice(0,100),entries:data.entries,created:Date.now()};await dbPut(imported);await refreshCount();await renderSets();toast(LANGS[language].imported)}catch(err){toast(LANGS[language].badFile)}finally{e.target.value=""}};
async function renderSets(){const sets=(await dbAll()).sort((a,b)=>b.created-a.created);$("setsList").innerHTML="";$("empty").hidden=sets.length>0;sets.forEach(s=>{const item=document.createElement("div");item.className="set-item";item.innerHTML=`<div class="set-icon">♫</div><div class="set-info"><h3>${escapeHTML(s.name)}</h3><p>${s.entries.length} ${s.entries.length===1?tr("oneRecording"):tr("manyRecordings")} · ${new Date(s.created).toLocaleDateString()}</p></div><div class="set-actions"><button class="primary small">${LANGS[language].practice}</button><button class="secondary small share">${LANGS[language].share}</button><button class="secondary small delete">${LANGS[language].del}</button></div>`;item.querySelector(".primary").onclick=()=>startPractice(s);item.querySelector(".share").onclick=()=>exportSet(s);item.querySelector(".delete").onclick=async()=>{if(confirm(`${tr("deleteConfirm")} "${s.name}" ${tr("deleteTail")}`)){await dbDelete(s.id);renderSets();refreshCount()}};$("setsList").appendChild(item)})}
function startPractice(set){practiceQueue=null;activeSet=set;activeIndex=0;$("autoCountdown").textContent="";show("practice");showQuestion(true)}
function startSmartReview(items){if(!items.length){toast(V11_TEXT[language].nothingDue);return}practiceQueue=items;activeSet={id:"smart-review",name:"Smart review",entries:items.map(x=>({...x.entry,_setId:x.setId,_reviewKey:x.key}))};activeIndex=0;$("autoCountdown").textContent="";show("practice");showQuestion(true)}
function showQuestion(keepKeyboard=false){cancelAuto();answered=false;const entry=activeSet.entries[activeIndex];practiceStartedAt=Date.now();$("progress").textContent=`${tr("progressWord")} ${activeIndex+1} / ${activeSet.entries.length}`;const input=$("typed");input.value="";input.disabled=false;$("checkBtn").disabled=false;$("feedback").textContent="";$("feedback").className="";$("nextBtn").hidden=true;$("playBtn").disabled=false;$("practiceAudio").src=entry.audio||"";if(keepKeyboard||document.activeElement===input)input.focus();}
function readJSON(key,fallback){try{return JSON.parse(localStorage.getItem(key)||"")||fallback}catch{return fallback}}
function writeJSON(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch(e){console.warn("StudySonic local stats storage is full",e)}}
function historyRows(){return readJSON(STATS_KEY,[])}
function reviewState(){return readJSON(REVIEW_KEY,{})}
function wordReviewKey(setId,answer){return String(setId)+"::"+normalizeAnswer(answer)}
function recordLearningResult(entry,correct){const now=Date.now(),setId=entry._setId||activeSet.id,key=entry._reviewKey||wordReviewKey(setId,entry.answer),elapsed=Math.max(0,now-practiceStartedAt),history=historyRows();history.push({at:now,setId,answer:entry.answer,correct,elapsed});writeJSON(STATS_KEY,history.slice(-5000));const state=reviewState(),old=state[key]||{interval:0,ease:2.5,reps:0,lapses:0};if(correct){old.reps++;old.interval=old.reps===1?1:old.reps===2?3:Math.max(4,Math.round((old.interval||3)*old.ease));old.ease=Math.min(2.8,old.ease+.08)}else{old.lapses++;old.reps=0;old.interval=0;old.ease=Math.max(1.3,old.ease-.2)}old.due=now+old.interval*86400000;old.last=now;old.lastCorrect=correct;old.answer=entry.answer;old.setId=setId;state[key]=old;writeJSON(REVIEW_KEY,state)}
function getDueItems(){const state=reviewState(),now=Date.now(),items=[];dbAll().then(sets=>{sets.forEach(set=>set.entries.forEach(entry=>{const key=wordReviewKey(set.id,entry.answer),st=state[key];if(!st||!st.due||st.due<=now)items.push({key,setId:set.id,entry:{...entry}})}));startSmartReview(items)}).catch(()=>toast(tr("storageUnsupported")))}
function finishAnswer(correct){if(answered)return;const entry=activeSet.entries[activeIndex];recordLearningResult(entry,correct);answered=true;$("feedback").textContent=correct?tr("correct"):tr("incorrect")+entry.answer;$("feedback").className=correct?"good":"bad";$("typed").disabled=true;$("checkBtn").disabled=true;$("nextBtn").hidden=false;$("nextBtn").textContent=activeIndex===activeSet.entries.length-1?tr("finish"):tr("next");}
$("playBtn").onclick=()=>speakEntry(activeSet.entries[activeIndex]);
$("checkBtn").onclick=()=>{if(answered)return;const guess=normalizeAnswer($("typed").value);if(!guess){toast(tr("typeFirst"));return}const correct=guess===normalizeAnswer(activeSet.entries[activeIndex].answer);finishAnswer(correct);if($('autoSpeakToggle').checked&&!$('autoAdvanceToggle').checked)scheduleAutoNext()};
$("nextBtn").onclick=()=>{cancelAuto();if(activeIndex<activeSet.entries.length-1){activeIndex++;showQuestion(true);if($("autoSpeakToggle").checked)speakEntry(activeSet.entries[activeIndex])}else{toast(tr("complete"));practiceQueue=null;show("library")}};
$("exitPractice").onclick=()=>{cancelAuto();window.speechSynthesis?.cancel();practiceQueue=null;show("library")};
