function mt(key){const pack=V11_TEXT[language]||V11_TEXT.en;return pack[key]||V11_TEXT.en[key]||key}
function renderAnalytics(){const t=V11_TEXT[language]||V11_TEXT.en,h=historyRows(),state=reviewState(),attempts=h.length,correct=h.filter(x=>x.correct).length,unique=new Set(h.map(x=>x.setId+"::"+normalizeAnswer(x.answer))).size,due=Object.values(state).filter(x=>x.due&&x.due<=Date.now()).length;$("analyticsTitle").textContent=t.analyticsTitle;$("analyticsEyebrow").textContent=t.analyticsEyebrow;$("analyticsDescription").textContent=t.analyticsDescription;$("statAttemptsLabel").textContent=t.attempts;$("statAccuracyLabel").textContent=t.accuracy;$("statWordsLabel").textContent=t.wordsPractised;$("statDueLabel").textContent=t.due;$("statAttempts").textContent=attempts;$("statAccuracy").textContent=attempts?Math.round(correct/attempts*100)+"%":"—";$("statWords").textContent=unique;$("statDue").textContent=due;$("weeklyTitle").textContent=t.weekly;$("weeklySubtitle").textContent=t.weeklySub;$("reviewTitle").textContent=t.reviewQueue;$("reviewDescription").textContent=t.reviewDescription;$("wordPerformanceTitle").textContent=t.wordPerformance;$("smartReviewButton").textContent="⚡ "+t.smartReview;const days=[];for(let i=6;i>=0;i--){const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-i);const start=d.getTime(),end=start+86400000;days.push({date:d,count:h.filter(x=>x.at>=start&&x.at<end).length})}const max=Math.max(1,...days.map(x=>x.count));$("weeklyChart").innerHTML=days.map(x=>`<div class="week-bar-wrap"><b>${x.count}</b><div class="week-bar" style="height:${Math.max(3,x.count/max*125)}px"></div><small>${x.date.toLocaleDateString(undefined,{weekday:"short"})}</small></div>`).join("");const dueRows=Object.entries(state).filter(([,v])=>v.due&&v.due<=Date.now()).sort((a,b)=>a[1].due-b[1].due).slice(0,6);$("reviewPreview").innerHTML=dueRows.length?dueRows.map(([k,v])=>`<div class="review-row"><span>${escapeHTML(v.answer||k.split("::").slice(1).join("::"))}</span><small>${v.lastCorrect?t.mastered:t.needsWork}</small></div>`).join(""):`<div class="analytics-empty">${attempts?t.noReview:t.noData}</div>`;const map={};h.forEach(x=>{const k=x.setId+"::"+normalizeAnswer(x.answer);map[k]??={answer:x.answer,total:0,correct:0};map[k].total++;if(x.correct)map[k].correct++});const rows=Object.values(map).sort((a,b)=>(a.correct/a.total)-(b.correct/b.total)).slice(0,10);$("wordPerformance").innerHTML=rows.length?`<div class="performance-list">${rows.map(x=>{const pct=Math.round(x.correct/x.total*100);return `<div class="performance-row"><span>${escapeHTML(x.answer)}</span><div class="performance-meter"><span style="width:${pct}%"></span></div><small>${pct}% · ${x.total} ${t.correct}</small></div>`}).join("")}</div>`:`<div class="analytics-empty">${t.noData}</div>`;}
