// V1 Mindmap Builder — local-first, HoodleMind-inspired hierarchical tree layout.
const MM_KEY="studiosonic-v8-mindmaps";
const MM_OLD_KEY="studiosonic-v7-mindmaps";
const MM_COLORS=["#65b7ee","#b15acb","#e64d5b","#f1c43b","#28c48a","#ff944d","#8b83ff","#e77ab5"];
let mindmaps=[],activeMindmapId=null,selectedNodeId=null,mmScale=1,mmPan={x:0,y:0},mmPointer=null,mmDragNode=null,mmSaveTimer=null;
const mmid=()=>"mm-"+Date.now().toString(36)+Math.random().toString(36).slice(2,7);
function loadMindmaps(){try{mindmaps=JSON.parse(localStorage.getItem(MM_KEY)||"[]");if(!Array.isArray(mindmaps))mindmaps=[]}catch{mindmaps=[]}}
function persistMindmaps(){localStorage.setItem(MM_KEY,JSON.stringify(mindmaps));const c=$("mindmapCount");if(c)c.textContent=mindmaps.length;const status=$("mindmapSaveStatus");if(status)status.textContent=mt("savedLocally")}
function activeMap(){return mindmaps.find(m=>m.id===activeMindmapId)}
function findNode(id,nodes=(activeMap()?.root?[activeMap().root]:[])){for(const n of nodes){if(n.id===id)return n;const found=findNode(id,n.children||[]);if(found)return found}return null}
function findParent(id,nodes=(activeMap()?.root?[activeMap().root]:[]),parent=null){for(const n of nodes){if(n.id===id)return parent;const found=findParent(id,n.children||[],n);if(found!==undefined)return found}return undefined}
function createMindmap(){const now=Date.now();const map={id:mmid(),title:mt("untitledMindmap"),created:now,updated:now,root:{id:mmid(),label:mt("centralTopic"),notes:"",color:"#3978ff",children:[]}};mindmaps.unshift(map);activeMindmapId=map.id;selectedNodeId=map.root.id;persistMindmaps();openMindmapEditor();}
function saveMindmapSoon(){const m=activeMap();if(!m)return;m.updated=Date.now();const status=$("mindmapSaveStatus");if(status)status.textContent=mt("saving");clearTimeout(mmSaveTimer);mmSaveTimer=setTimeout(()=>{persistMindmaps();},180)}
function renderMindmapLibrary(){persistMindmaps();renderSidebarMindmapQuick();const grid=$("mindmapGrid"),empty=$("mindmapEmpty");if(!grid)return;grid.innerHTML="";empty.hidden=mindmaps.length>0;mindmaps.sort((a,b)=>b.updated-a.updated).forEach(m=>{const card=document.createElement("article");card.className="mindmap-card";const svg=document.createElementNS("http://www.w3.org/2000/svg","svg");svg.setAttribute("viewBox","0 0 420 145");svg.setAttribute("class","mindmap-preview");const center=svgEl("g");const root=svgEl("rect",{x:177,y:60,width:66,height:25,rx:5,fill:"#27334b",stroke:"#3978ff"});center.appendChild(root);for(let i=0;i<(m.root.children||[]).length;i++){const color=m.root.children[i].color||MM_COLORS[i%MM_COLORS.length],left=i%2===0,x1=210,y1=72,x2=left?95:325,y2=25+(i%3)*45;center.appendChild(svgEl("path",{d:`M ${x1} ${y1} C ${(x1+x2)/2} ${y1}, ${(x1+x2)/2} ${y2}, ${x2} ${y2}`,stroke:color,"stroke-width":2,fill:"none"}));center.appendChild(svgEl("path",{d:`M ${x2} ${y2} l ${left?-38:38} 0`,stroke:color,"stroke-width":1.5,fill:"none"}))}svg.appendChild(center);card.appendChild(svg);const info=document.createElement("div");info.className="mindmap-card-info";const title=document.createElement("h3");title.textContent=m.title||mt("untitledMindmap");const p=document.createElement("p");const count=countNodes(m.root)-1;p.textContent=`${count} ${count===1?mt("branch"):mt("branches")} · ${mt("edited")} ${new Date(m.updated).toLocaleDateString()}`;const actions=document.createElement("div");actions.className="mindmap-card-actions";const open=document.createElement("button");open.className="primary";open.textContent=mt("open");open.onclick=()=>{activeMindmapId=m.id;selectedNodeId=m.root.id;openMindmapEditor()};const del=document.createElement("button");del.className="secondary";del.textContent=mt("delete");del.onclick=()=>{if(confirm(`${mt("delete")} “${m.title}”?`)){mindmaps=mindmaps.filter(x=>x.id!==m.id);persistMindmaps();renderMindmapLibrary()}};actions.append(open,del);info.append(title,p,actions);card.append(info);grid.append(card)});}
function renderSidebarMindmapQuick(){const box=$("sidebarMindmapItems");if(!box)return;box.innerHTML="";if(!mindmaps.length){const empty=document.createElement("div");empty.className="sidebar-quick-empty";empty.textContent=mt("quickEmpty");box.append(empty);return}mindmaps.slice().sort((a,b)=>b.updated-a.updated).forEach(m=>{const row=document.createElement("button");row.type="button";row.className="sidebar-mindmap-item";const mini=document.createElementNS("http://www.w3.org/2000/svg","svg");mini.setAttribute("viewBox","0 0 100 60");mini.setAttribute("class","sidebar-mindmap-thumb");mini.append(svgEl("rect",{x:40,y:24,width:20,height:12,rx:3,fill:"#26334b",stroke:"#3978ff"}));(m.root.children||[]).slice(0,4).forEach((n,i)=>{const left=i%2===0,col=n.color||MM_COLORS[i%MM_COLORS.length],x=left?40:60,y=30+(i%3-1)*15;mini.append(svgEl("path",{d:`M 50 30 Q ${x} ${y} ${left?8:92} ${y}`,stroke:col,"stroke-width":1.5,fill:"none"}))});const name=document.createElement("span");name.className="sidebar-mindmap-name";name.textContent=m.title||mt("untitledMindmap");row.append(mini,name);row.onclick=()=>{activeMindmapId=m.id;selectedNodeId=m.root.id;const q=$("sidebarMindmapQuick");if(q)q.hidden=true;openMindmapEditor()};box.append(row)})}function countNodes(n){return 1+(n.children||[]).reduce((s,c)=>s+countNodes(c),0)}
function svgEl(tag,attrs={}){const el=document.createElementNS("http://www.w3.org/2000/svg",tag);Object.entries(attrs).forEach(([k,v])=>el.setAttribute(k,String(v)));return el}
let mmAnimateOnOpen=false;
function openMindmapEditor(){const m=activeMap();if(!m)return;$("mindmapTitleInput").value=m.title||mt("untitledMindmap");selectedNodeId=selectedNodeId||m.root.id;mmScale=1;mmPan={x:0,y:0};show("mindmapEditor");selectMindmapNode(selectedNodeId);mmAnimateOnOpen=true;renderMindmap();}
function mainBranchColors(){return MM_COLORS}
function layoutMindmap(){const m=activeMap();if(!m)return{nodes:[],edges:[]};const root=m.root,cx=1000,cy=650,nodes=[],edges=[];nodes.push({node:root,x:cx,y:cy,root:true,color:root.color||"#3978ff",depth:0,side:0});const branches=root.children||[];const quads=[[-1,-1], [1,-1], [1,1], [-1,1]];branches.forEach((branch,i)=>{const [sx,sy]=quads[i%4],color=branch.color||MM_COLORS[i%MM_COLORS.length];const baseX=cx+sx*235,baseY=cy+sy*155;const countLeaves=n=>{if(!n.children?.length)return 1;return n.children.reduce((a,c)=>a+countLeaves(c),0)};const step=43;const total=countLeaves(branch);let cursor=baseY-sy*(total-1)*step/2;
 function place(node,depth,parent,forcedY=null){let leaves=countLeaves(node),y;if(forcedY!==null)y=forcedY;else if(!node.children?.length){y=cursor;cursor+=sy*step}else{const start=cursor;node.children.forEach(ch=>place(ch,depth+1,node));const end=cursor-sy*step;y=(start+end)/2}const x=cx+sx*(235+(depth-1)*190);const offset=node.offset||{x:0,y:0};const item={node,x:x+(offset.x||0),y:y+(offset.y||0),root:false,main:depth===1,color,depth,side:sx};nodes.push(item);if(parent){const px=parent.x,py=parent.y,mid=(px+x)/2;edges.push({from:parent,to:item,color});}return item}
 // Branch root sits in its quadrant; distribute its descendants outward in a compact hierarchy.
 const rootItem={node:branch,x:baseX+(branch.offset?.x||0),y:baseY+(branch.offset?.y||0),root:false,main:true,color,depth:1,side:sx};nodes.push(rootItem);let leafCursor=baseY-sy*(Math.max(1,total-1)*step)/2;
 function descend(parentItem,child,depth){const leaves=countLeaves(child);let y;if(!child.children?.length){y=leafCursor;leafCursor+=sy*step}else{const start=leafCursor;const childItems=[];child.children.forEach(grand=>{const it=descend(null,grand,depth+1);childItems.push(it)});const end=leafCursor-sy*step;y=(start+end)/2;const x=cx+sx*(235+(depth-1)*190)+(child.offset?.x||0),off=child.offset||{x:0,y:0};const item={node:child,x,y:y+(off.y||0),root:false,main:false,color:child.color||color,depth,side:sx};nodes.push(item);if(parentItem)edges.push({from:parentItem,to:item,color:item.color});childItems.forEach(it=>edges.push({from:item,to:it,color:it.color||item.color}));return item}
 const off=child.offset||{x:0,y:0};const x=cx+sx*(235+(depth-1)*190)+(off.x||0);const item={node:child,x,y:y+(off.y||0),root:false,main:false,color:child.color||color,depth,side:sx};nodes.push(item);if(parentItem)edges.push({from:parentItem,to:item,color:item.color});return item}
 branch.children?.forEach(ch=>descend(rootItem,ch,2));edges.push({from:nodes[0],to:rootItem,color});});return{nodes,edges}}
function renderMindmap(){const m=activeMap();if(!m)return;const animateThisRender=mmAnimateOnOpen;mmAnimateOnOpen=false;const group=$("mindmapViewport");group.innerHTML="";const {nodes,edges}=layoutMindmap();const transform=svgEl("g",{transform:`translate(${mmPan.x} ${mmPan.y}) translate(1000 650) scale(${mmScale}) translate(-1000 -650)`});edges.forEach((e,i)=>{const dx=e.to.x-e.from.x,dir=Math.sign(dx)||1;const c1=e.from.x+dx*.48,c2=e.to.x-dx*.48;const path=svgEl("path",{class:"mindmap-connector"+(animateThisRender?" mm-reveal":""),d:`M ${e.from.x} ${e.from.y} C ${c1} ${e.from.y}, ${c2} ${e.to.y}, ${e.to.x} ${e.to.y}`,stroke:e.color});if(animateThisRender){const length=Math.ceil(Math.hypot(dx,e.to.y-e.from.y)*1.15);path.style.setProperty("--mm-line-length",length+"px");path.style.setProperty("--mm-delay",Math.min(i*38,520)+"ms")}transform.append(path)});
 nodes.forEach((item,index)=>{const n=item.node,g=svgEl("g",{class:`mindmap-node${item.main?" main-branch":""}${item.root?" mindmap-root":""}${selectedNodeId===n.id?" selected":""}${animateThisRender?" mm-reveal":""}`,"data-node-id":n.id});if(animateThisRender){g.style.setProperty("--mm-delay",Math.min(90+index*34,760)+"ms");g.style.setProperty("--mm-from-x",(item.x<1000?-18:18)+"px");g.style.setProperty("--mm-from-y",(item.y<650?-10:10)+"px");}if(item.root){const label=n.label||"Central topic",w=Math.max(160,Math.min(320,label.length*14+38));g.append(svgEl("rect",{x:item.x-w/2,y:item.y-34,width:w,height:68,rx:9}));const text=svgEl("text",{x:item.x,y:item.y+8,"text-anchor":"middle"});text.textContent=label;g.append(text)}else{const anchor=item.side<0?"end":"start",tx=item.x+(item.side<0?-10:10),label=n.label||"New branch",boxW=Math.max(82,Math.min(280,label.length*9.2+24)),boxX=item.main?(item.side<0?tx-boxW:tx):Math.min(item.x-5,tx-5),boxY=item.y-22;const hit=svgEl("rect",{class:"node-hit",x:boxX,y:boxY,width:item.main?boxW:Math.max(70,label.length*9+20),height:32,rx:item.main?6:5});if(item.main)hit.setAttribute("style",`--branch-color:${item.color}`);g.append(hit);const text=svgEl("text",{x:item.main?boxX+boxW/2:tx,y:item.y+5,"text-anchor":item.main?"middle":anchor});text.textContent=label;g.append(text);if(n.notes){const dot=svgEl("circle",{cx:item.x,cy:item.y,r:3.2,fill:item.color||item.color||item.node.color||item.color||"#fff"});g.append(dot)}}g.addEventListener("click",e=>{e.stopPropagation();selectMindmapNode(n.id)});g.addEventListener("pointerdown",e=>{if(e.target.closest("text")||e.target.closest("rect")){e.stopPropagation();mmDragNode={id:n.id,startX:e.clientX,startY:e.clientY,offset:{...(n.offset||{})}}}});transform.append(g)});group.append(transform);}
function selectMindmapNode(id){const n=findNode(id);if(!n)return;selectedNodeId=id;const empty=$("nodeInspector").querySelector(".inspector-empty"),content=$("inspectorContent");empty.hidden=true;content.hidden=false;$("nodeLabelInput").value=n.label||"";$("nodeNotesInput").value=n.notes||"";$("nodeColorInput").value=n.color||"#69aee8";$("inspectorHeading").textContent=id===activeMap().root.id?mt("centralTopic"):mt("branchDetails");$("editNodeBtn").disabled=false;renderMindmap()}
function updateSelectedNode(){const n=findNode(selectedNodeId);if(!n)return;n.label=$("nodeLabelInput").value.trim()||mt("untitledTopic");n.notes=$("nodeNotesInput").value;n.color=$("nodeColorInput").value;if(n===activeMap().root)activeMap().title=$("mindmapTitleInput").value||"Untitled mindmap";saveMindmapSoon();renderMindmap()}
function addMindmapNode(parentId,label=mt("newBranch")){const parent=findNode(parentId);if(!parent)return;const siblings=parent.children||(parent.children=[]);const color=parent===activeMap().root?MM_COLORS[siblings.length%MM_COLORS.length]:(parent.color||MM_COLORS[0]);const node={id:mmid(),label,notes:"",color,children:[]};siblings.push(node);selectedNodeId=node.id;saveMindmapSoon();renderMindmap();selectMindmapNode(node.id)}
function deleteSelectedMindmapNode(){if(!selectedNodeId||selectedNodeId===activeMap().root.id)return;const parent=findParent(selectedNodeId);if(!parent)return;parent.children=parent.children.filter(n=>n.id!==selectedNodeId);selectedNodeId=parent.id;saveMindmapSoon();renderMindmap();selectMindmapNode(parent.id)}
function fitMindmap(){mmScale=1;mmPan={x:0,y:0};renderMindmap()}
function zoomMindmap(factor){mmScale=Math.max(.22,Math.min(4.5,mmScale*factor));renderMindmap()}
function buildMindmapExportCanvas(){
 const svg=$("mindmapSvg").cloneNode(true),group=svg.querySelector("#mindmapViewport");
 const {nodes}=layoutMindmap();
 let minX=Infinity,minY=Infinity,maxX=-Infinity,maxY=-Infinity;
 nodes.forEach(item=>{const label=item.node.label||"New branch",w=item.root?Math.max(160,Math.min(320,label.length*14+38)):Math.max(70,label.length*10+28);const left=item.root?item.x-w/2:(item.side<0?item.x-w-12:item.x-4);const right=item.root?item.x+w/2:(item.side<0?item.x+4:item.x+w+12);minX=Math.min(minX,left);maxX=Math.max(maxX,right);minY=Math.min(minY,item.y-45);maxY=Math.max(maxY,item.y+45)});
 if(!Number.isFinite(minX)){minX=0;minY=0;maxX=2000;maxY=1300}
 const pad=95;minX-=pad;minY-=pad;maxX+=pad;maxY+=pad;
 const vbW=Math.max(500,maxX-minX),vbH=Math.max(350,maxY-minY),scale=Math.min(2,Math.max(1,4200/Math.max(vbW,vbH)));
 const width=Math.round(vbW*scale),height=Math.round(vbH*scale);
 svg.setAttribute("viewBox",`${minX} ${minY} ${vbW} ${vbH}`);svg.setAttribute("width",width);svg.setAttribute("height",height);svg.setAttribute("xmlns","http://www.w3.org/2000/svg");
 const oldTransform=group.querySelector(":scope > g");if(oldTransform)oldTransform.removeAttribute("transform");
 const bg=svgEl("rect",{x:minX,y:minY,width:vbW,height:vbH,fill:"#ffffff"});svg.insertBefore(bg,svg.firstChild);
 const style=svgEl("style");style.textContent='.mindmap-connector{fill:none;stroke-width:2.5;stroke-linecap:round;opacity:1}.mindmap-node text{font-family:Arial,sans-serif;fill:#202638;font-size:17px;font-weight:500;stroke:#fff;stroke-width:4px;stroke-linejoin:round;paint-order:stroke}.mindmap-node.main-branch text{font-size:19px;font-weight:700}.mindmap-node .node-hit{fill:transparent;stroke:transparent}.mindmap-node.selected text{fill:#202638;font-weight:700}.mindmap-root rect{fill:#fff;stroke:#3978ff;stroke-width:2}.mindmap-root text{font-family:Arial,sans-serif;font-size:25px;font-weight:800;fill:#172033;stroke:none}';svg.insertBefore(style,bg.nextSibling);
 return new Promise((resolve,reject)=>{const data=new XMLSerializer().serializeToString(svg),url=URL.createObjectURL(new Blob([data],{type:"image/svg+xml;charset=utf-8"})),img=new Image();img.onload=()=>{const c=document.createElement("canvas");c.width=width;c.height=height;const ctx=c.getContext("2d");ctx.fillStyle="#fff";ctx.fillRect(0,0,width,height);ctx.drawImage(img,0,0,width,height);URL.revokeObjectURL(url);resolve(c)};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error("Could not render the mindmap"))};img.src=url});
}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function safeMindmapFilename(ext){return (activeMap()?.title||"mindmap").trim().replace(/[^a-z0-9-_]+/gi,"-").replace(/^-|-$/g,"")||"mindmap"}
async function exportMindmapPNG(){try{toast(mt("preparingPNG"));const canvas=await buildMindmapExportCanvas();const blob=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error("PNG encoding failed")),"image/png"));downloadBlob(blob,safeMindmapFilename(".png")+".png");toast(mt("pngExported"))}catch(e){console.error(e);toast(mt("pngFailed"))}}
function jpegCanvasToPDF(canvas){return new Promise((resolve,reject)=>canvas.toBlob(async blob=>{if(!blob){reject(new Error("JPEG encoding failed"));return}const jpg=new Uint8Array(await blob.arrayBuffer()),W=595.28,H=841.89,margin=24,ratio=Math.min((W-margin*2)/canvas.width,(H-margin*2)/canvas.height),dw=canvas.width*ratio,dh=canvas.height*ratio,x=(W-dw)/2,y=(H-dh)/2;const enc=new TextEncoder(),parts=[],offsets=[];let length=0;const push=b=>{parts.push(b);length+=b.length},str=s=>enc.encode(s);push(str("%PDF-1.4\n%âãÏÓ\n"));const obj=(n,body)=>{offsets[n]=length;push(str(`${n} 0 obj\n${body}\nendobj\n`))};obj(1,"<< /Type /Catalog /Pages 2 0 R >>");obj(2,"<< /Type /Pages /Kids [3 0 R] /Count 1 >>");obj(3,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${W} ${H}] /Resources << /XObject << /Im0 4 0 R >> >> /Contents 5 0 R >>`);offsets[4]=length;push(str(`4 0 obj\n<< /Type /XObject /Subtype /Image /Width ${canvas.width} /Height ${canvas.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpg.length} >>\nstream\n`));push(jpg);push(str("\nendstream\nendobj\n"));const content=`q\n${dw.toFixed(2)} 0 0 ${dh.toFixed(2)} ${x.toFixed(2)} ${y.toFixed(2)} cm\n/Im0 Do\nQ`;obj(5,`<< /Length ${str(content).length} >>\nstream\n${content}\nendstream`);const xref=length;push(str(`xref\n0 6\n0000000000 65535 f \n${offsets.slice(1).map(v=>String(v).padStart(10,"0")+" 00000 n \n").join("")}trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`));resolve(new Blob(parts,{type:"application/pdf"}));},"image/jpeg",.96))}
