function bindMindmapUI(){loadMindmaps();persistMindmaps();$("createMindmapHero").onclick=createMindmap;$("newMindmapBtn").onclick=createMindmap;$("emptyMindmapBtn").onclick=createMindmap;$("sidebarNewMindmap").onclick=()=>{const q=$("sidebarMindmapQuick");if(q)q.hidden=true;createMindmap()};$("backMindmaps").onclick=()=>show("mindmaps");$("addMainBranch").onclick=()=>addMindmapNode(activeMap().root.id);$("addChildNode").onclick=()=>addMindmapNode(selectedNodeId);$("addSiblingNode").onclick=()=>{if(selectedNodeId===activeMap().root.id){addMindmapNode(selectedNodeId);return}const parent=findParent(selectedNodeId);addMindmapNode(parent?.id||activeMap().root.id)};$("deleteMindmapNode").onclick=()=>{if(confirm(mt("deleteNodeConfirm")))deleteSelectedMindmapNode()};$("fitMindmap").onclick=fitMindmap;$("zoomIn").onclick=()=>zoomMindmap(1.18);$("zoomOut").onclick=()=>zoomMindmap(.84);$("exportMindmap").onclick=exportMindmapPNG;$("exportMindmapPDF").onclick=exportMindmapPDF;$("editNodeBtn").onclick=()=>$("nodeLabelInput").focus();$("mindmapTitleInput").oninput=()=>{const m=activeMap();if(m){m.title=$("mindmapTitleInput").value;saveMindmapSoon();renderMindmapLibrary()}};$("nodeLabelInput").oninput=updateSelectedNode;$("nodeNotesInput").oninput=updateSelectedNode;$("nodeColorInput").oninput=updateSelectedNode;
 const wrap=$("mindmapCanvasWrap");wrap.addEventListener("pointerdown",e=>{if(e.target.closest(".mindmap-node"))return;mmPointer={x:e.clientX,y:e.clientY,pan:{...mmPan}};wrap.setPointerCapture(e.pointerId)});wrap.addEventListener("pointermove",e=>{if(mmDragNode){const rect=wrap.getBoundingClientRect(),dx=(e.clientX-mmDragNode.startX)*2000/rect.width/mmScale,dy=(e.clientY-mmDragNode.startY)*1300/rect.height/mmScale;const n=findNode(mmDragNode.id);if(n){n.offset={x:(mmDragNode.offset.x||0)+dx,y:(mmDragNode.offset.y||0)+dy};renderMindmap()}return}if(mmPointer){const rect=wrap.getBoundingClientRect();mmPan={x:mmPointer.pan.x+(e.clientX-mmPointer.x)*2000/rect.width,y:mmPointer.pan.y+(e.clientY-mmPointer.y)*1300/rect.height};renderMindmap()}});wrap.addEventListener("pointerup",()=>{if(mmDragNode){saveMindmapSoon();mmDragNode=null}mmPointer=null});wrap.addEventListener("pointercancel",()=>{mmDragNode=null;mmPointer=null});wrap.addEventListener("wheel",e=>{e.preventDefault();zoomMindmap(e.deltaY<0?1.08:.92)},{passive:false});
 // Native iOS/iPadOS two-finger pinch zoom. One-finger node selection/drag and canvas panning remain intact.
 let pinchStartDistance=0,pinchStartScale=1;
 const touchDistance=touches=>{const dx=touches[0].clientX-touches[1].clientX,dy=touches[0].clientY-touches[1].clientY;return Math.hypot(dx,dy)};
 wrap.addEventListener("touchstart",e=>{if(e.touches.length===2){e.preventDefault();pinchStartDistance=touchDistance(e.touches);pinchStartScale=mmScale;mmPointer=null;mmDragNode=null;}},{passive:false});
 wrap.addEventListener("touchmove",e=>{if(e.touches.length===2&&pinchStartDistance>0){e.preventDefault();const next=pinchStartScale*(touchDistance(e.touches)/pinchStartDistance);mmScale=Math.max(.22,Math.min(4.5,next));renderMindmap();}},{passive:false});
 const endPinch=()=>{pinchStartDistance=0;pinchStartScale=mmScale;};wrap.addEventListener("touchend",e=>{if(e.touches.length<2)endPinch()},{passive:true});wrap.addEventListener("touchcancel",endPinch,{passive:true});
}
